func (s *Store) UpdateSampleType(id string, name, containerType *string, tempMin, tempMax *float64, rqc, rc, nc *bool) error {
	q := `UPDATE sample_types SET `
	args := []interface{}{}
	argN := 1
	if name != nil {
		q += fmt.Sprintf("name=$%d,", argN)
		args = append(args, *name)
		argN++
	}
	if containerType != nil {
		q += fmt.Sprintf("container_type=$%d,", argN)
		args = append(args, *containerType)
		argN++
	}
	if tempMin != nil {
		q += fmt.Sprintf("temperature_min_c=$%d,", argN)
		args = append(args, *tempMin)
		argN++
	}
	if tempMax != nil {
		q += fmt.Sprintf("temperature_max_c=$%d,", argN)
		args = append(args, *tempMax)
		argN++
	}
	if rqc != nil {
		q += fmt.Sprintf("requires_qualified_collector=$%d,", argN)
		args = append(args, *rqc)
		argN++
	}
	if rc != nil {
		q += fmt.Sprintf("requires_cooled=$%d,", argN)
		args = append(args, *rc)
		argN++
	}
	if nc != nil {
		q += fmt.Sprintf("no_consolidation=$%d,", argN)
		args = append(args, *nc)
		argN++
	}
	q = q[:len(q)-1] // Remove trailing comma
	q += fmt.Sprintf(" WHERE id=$%d", argN)
	args = append(args, id)
	_, err := s.db.Exec(q, args...)
	return err
}

