func (s *Store) GetJourney(id string) (*models.JourneyPlan, error) {
	j := &models.JourneyPlan{}
	var parentID, replanStatus, replacementID sql.NullString
	var estDelivery sql.NullTime
	var totalCost sql.NullFloat64
	err := s.db.QueryRow(`SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, replan_status, replacement_journey_id FROM journeys WHERE id=$1`, id).Scan(&j.JourneyID, &parentID, &j.PlanVersion, &j.RouteMode, &j.Status, &estDelivery, &totalCost, &j.Valid, &replanStatus, &replacementID)
	if err != nil {
		return nil, err
	}
	if parentID.Valid {
		j.ParentJourneyID = parentID.String
	}
	if estDelivery.Valid {
		j.EstimatedDeliveryAt = &estDelivery.Time
	}
	if totalCost.Valid {
		j.TotalCostUnits = totalCost.Float64
	}
	if replanStatus.Valid {
		j.ReplanStatus = replanStatus.String
	}
	// Get sample IDs
	rows, err := s.db.Query(`SELECT sample_id FROM journeys WHERE id=$1 OR parent_journey_id=$1 OR replacement_journey_id=$1`, id)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var sid string
			rows.Scan(&sid)
			j.SampleIDs = append(j.SampleIDs, sid)
		}
	}
	if len(j.SampleIDs) == 0 {
		j.SampleIDs = []string{}
	}
	// Get legs
	legRows, err := s.db.Query(`SELECT COALESCE(assignment_id::text,''), sequence, status, COALESCE(from_location_id::text,''), COALESCE(to_location_id::text,''), COALESCE(worker_id::text,''), sample_id FROM journey_legs WHERE journey_id=$1 ORDER BY sequence`, id)
	if err == nil {
		defer legRows.Close()
		for legRows.Next() {
			var l models.JourneyLeg
			var aid, flid, tlid, wid, sid string
			legRows.Scan(&aid, &l.Sequence, &l.Status, &flid, &tlid, &wid, &sid)
			l.AssignmentID = aid
			l.FromLocationID = flid
			l.ToLocationID = tlid
			l.WorkerID = wid
			l.SampleID = sid
			j.Legs = append(j.Legs, l)
		}
	}
	if j.Legs == nil {
		j.Legs = []models.JourneyLeg{}
	}
	// Get stops
	stopRows, err := s.db.Query(`SELECT id, COALESCE(location_id::text,''), stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, id)
	if err == nil {
		defer stopRows.Close()
		for stopRows.Next() {
			var s models.JourneyStop
			var locID sql.NullString
			var est time.Time
			var comp sql.NullTime
			var lat, lng sql.NullFloat64
			stopRows.Scan(&s.StopID, &locID, &s.StopType, &s.Sequence, &est, &s.DwellMinutes, &lat, &lng, &comp)
			if locID.Valid {
				s.LocationID = locID.String
			}
			s.EstimatedAt = est
			if comp.Valid {
				s.CompletedAt = &comp.Time
			}
			if lat.Valid && lng.Valid {
				s.Coordinate = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
			}
			j.OrderedStops = append(j.OrderedStops, s)
		}
	}
	if j.OrderedStops == nil {
		j.OrderedStops = []models.JourneyStop{}
	}
	return j, nil
}

