func (s *Store) ConfirmHandoff(id, userID string, isSender bool) (bool, error) {
	var fromID, toID string
	var senderConf, receiverConf bool
	err := s.db.QueryRow(`SELECT from_user_id, to_user_id, sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, id).Scan(&fromID, &toID, &senderConf, &receiverConf)
	if err != nil {
		return false, err
	}
	if isSender {
		if userID != fromID {
			return false, fmt.Errorf("not the sender")
		}
		if senderConf {
			return false, fmt.Errorf("already confirmed")
		}
		_, err = s.db.Exec(`UPDATE handoffs SET sender_confirmed=true WHERE id=$1`, id)
	} else {
		if userID != toID {
			return false, fmt.Errorf("not the receiver")
		}
		if receiverConf {
			return false, fmt.Errorf("already confirmed")
		}
		_, err = s.db.Exec(`UPDATE handoffs SET receiver_confirmed=true WHERE id=$1`, id)
	}
	if err != nil {
		return false, err
	}
	// Check if both confirmed
	var sc, rc bool
	s.db.QueryRow(`SELECT sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, id).Scan(&sc, &rc)
	if sc && rc {
		_, err = s.db.Exec(`UPDATE handoffs SET completed_at=now() WHERE id=$1`, id)
		return true, err
	}
	return false, nil
}

func (s *Store) RecordHandlingCheckpoint(sampleID, userID, containerType string, tempC float64) (bool, string, error) {
