		ids = append(ids, id)
	}
	var results []models.SampleState
	for _, id := range ids {
		s, err := s.GetSample(id)
		if err == nil {
			results = append(results, *s)
		}
	}
	return results, nil
}

func (s *Store) GetAllWorkers() ([]map[string]interface{}, error) {
	rows, err := s.db.Query(`SELECT u.id, u.full_name FROM users u JOIN user_roles ur ON u.id=ur.user_id WHERE u.active=true AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var workers []map[string]interface{}
	for rows.Next() {
		var id, name string
		rows.Scan(&id, &name)
		w := map[string]interface{}{
			"workerId":  id,
			"fullName":  name,
			"available": true,
			"status":    "available",
			"capacityUnits": 10,
			"assignmentCount": 0,
			"locationStale": true,
		}
		// count assignments
		var count int
		s.db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('offered','accepted')`, id).Scan(&count)
		w["assignmentCount"] = count
		if count > 0 {
			w["available"] = false
			w["status"] = "unavailable"
		}
		workers = append(workers, w)
	}
	return workers, nil
}

func (s *Store) ConfigureCapacityForLocation(id string, regular, cooled int) error {
	_, err := s.db.Exec(`UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`, id, regular, cooled)
	return err
}

func (s *Store) ConfigureCapacityForConnection(id string, regular, cooled int) error {
	_, err := s.db.Exec(`UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE id=$1`, id, regular, cooled)
	return err
}", "path": "/workspace/backend/store/pg/store.go"}

{"command": "create", "file_text": "package mongo

import (
	"context"
	"lab-logistics/backend/models"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type AuditStore struct {
	client *mongo.Client
	coll   *mongo.Collection
}

func New(uri string) (*AuditStore, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	client, err := mongo.Connect(ctx, options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}
	if err := client.Ping(ctx, nil); err != nil {
		return nil, err
	}
	db := client.Database("lab_logistics")
	return &AuditStore{client: client, coll: db.Collection("audit_logs")}, nil
}

func (s *AuditStore) Init(ctx context.Context) error {
	indexes := []mongo.IndexModel{
		{Keys: bson.D{{Key: "entityId", Value: 1}}},
		{Keys: bson.D{{Key: "actorId", Value: 1}}},
		{Keys: bson.D{{Key: "entityType", Value: 1}}},
		{Keys: bson.D{{Key: "occurredAt", Value: -1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
	}
	_, err := s.coll.Indexes().CreateMany(ctx, indexes)
	return err
}

func (s *AuditStore) Insert(ctx context.Context, entry models.AuditEntry) error {
	_, err := s.coll.InsertOne(ctx, entry)
	return err
}

func (s *AuditStore) Search(ctx context.Context, entityType, entityID string, offset, limit int, order string) (*models.AuditSearchResult, error) {
	filter := bson.M{}
	if entityType != "" {
		filter["entityType"] = entityType
	}
	if entityID != "" {
		filter["entityId"] = entityID
	}

	sortOrder := -1
	if order == "oldest_first" {
		sortOrder = 1
	}

	total, _ := s.coll.CountDocuments(ctx, filter)

	opts := options.Find().
		SetSort(bson.D{{Key: "occurredAt", Value: sortOrder}}).
		SetSkip(int64(offset)).
		SetLimit(int64(limit))

	cursor, err := s.coll.Find(ctx, filter, opts)
	if err != nil {
		return nil, err
	}
	defer cursor.Close(ctx)

	var entries []models.AuditEntry
	if err := cursor.All(ctx, &entries); err != nil {
		return nil, err
	}
	if entries == nil {
		entries = []models.AuditEntry{}
	}

	hasMore := offset+len(entries) < int(total)
	result := &models.AuditSearchResult{
		Entries:  entries,
		Total:    int(total),
		Returned: len(entries),
		Offset:   offset,
		Limit:    limit,
		Order:    order,
		HasMore:  hasMore,
	}
	if hasMore {
		result.NextOffset = offset + len(entries)
	}
	return result, nil
}

func (s *AuditStore) Close(ctx context.Context) error {
	return s.client.Disconnect(ctx)
}", "path": "/workspace/backend/store/mongo/audit.go"}

{"command": "create", "file_text": "package redisstore

import (
	"context"
	"encoding/json"
	"fmt"
	"lab-logistics/backend/models"
	"strconv"
	"time"

	"github.com/redis/go-redis/v9"
)

type EventStore struct {
	client *redis.Client
}

func New(addr string) (*EventStore, error) {
	client := redis.NewClient(&redis.Options{Addr: addr})
	if err := client.Ping(context.Background()).Err(); err != nil {
		return nil, err
	}
	return &EventStore{client: client}, nil
}

func (s *EventStore) Init(ctx context.Context) error {
	return s.client.Set(ctx, "event:counter", 0, 0).Err()
}

func (s *EventStore) NextID(ctx context.Context) (int64, error) {
	return s.client.Incr(ctx, "event:counter").Result()
}

func (s *EventStore) Publish(ctx context.Context, event models.RealtimeEvent) error {
	id, err := s.NextID(ctx)
	if err != nil {
		return err
	}
	event.ID = id
	event.CreatedAt = time.Now()
	data, err := json.Marshal(event)
	if err != nil {
		return err
	}
	pipe := s.client.Pipeline()
	pipe.XAdd(ctx, &redis.XAddArgs{
		Stream: "events",
		Values: map[string]interface{}{"data": string(data)},
	})
	pipe.Set(ctx, fmt.Sprintf("event:%d", id), string(data), 24*time.Hour)
	_, err = pipe.Exec(ctx)
	return err
}

func (s *EventStore) EventsSince(ctx context.Context, since int64) ([]models.RealtimeEvent, error) {
	key := fmt.Sprintf("event:%d", since+1)
	events := []models.RealtimeEvent{}
	for i := since + 1; ; i++ {
		data, err := s.client.Get(ctx, fmt.Sprintf("event:%d", i)).Result()
		if err != nil {
			break
		}
		var event models.RealtimeEvent
		json.Unmarshal([]byte(data), &event)
		events = append(events, event)
	}
	return events, nil
}

func (s *EventStore) LatestEventID(ctx context.Context) (int64, error) {
	val, err := s.client.Get(ctx, "event:counter").Result()
	if err != nil {
		return 0, nil
	}
	return strconv.ParseInt(val, 10, 64)
}

func (s *EventStore) Close() error {
	return s.client.Close()
}", "path": "/workspace/backend/store/redis/events.go"}

{"command": "create", "file_text": "package serviceability

import (
	"lab-logistics/backend/store/pg"
	"math"
	"sync"
	"time"
)

type Calculator struct {
	store     *pg.Store
	mu        sync.RWMutex
	version   int
	regions   []regionEntry
	computing bool
}

type regionEntry struct {
	LocationID string  `json:"locationId"`
	Name       string  `json:"name"`
	Latitude   float64 `json:"latitude"`
	Longitude  float64 `json:"longitude"`
	CoverageKm float64 `json:"coverageKm"`
}

func New(s *pg.Store) *Calculator {
	return &Calculator{store: s, version: 1}
}

func (c *Calculator) Compute() {
	c.mu.Lock()
	c.computing = true
	c.mu.Unlock()

	defer func() {
		c.mu.Lock()
		c.computing = false
		c.mu.Unlock()
	}()

	locs, err := c.store.GetAllLocations()
	if err != nil {
		return
	}

	var regions []regionEntry
	for _, l := range locs {
		if !l.Active {
			continue
		}
		if l.Functions.CollectionPoint != nil && *l.Functions.CollectionPoint {
			regions = append(regions, regionEntry{
				LocationID: l.LocationID,
				Name:       l.Name,
				Latitude:   l.Coordinate.Latitude,
				Longitude:  l.Coordinate.Longitude,
				CoverageKm: l.CoverageKm,
			})
		}
	}

	c.mu.Lock()
	c.regions = regions
	c.version++
	c.mu.Unlock()
}

func (c *Calculator) GetVersion() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.version
}

func (c *Calculator) CheckServiceability(lat, lng float64, sampleTypeID string, deadline time.Time) (bool, int, []regionEntry) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	var serviceableRegions []regionEntry
	for _, r := range c.regions {
		dist := haversine(lat, lng, r.Latitude, r.Longitude)
		if dist <= r.CoverageKm {
			serviceableRegions = append(serviceableRegions, r)
		}
	}

	if len(serviceableRegions) == 0 {
		return false, c.version, serviceableRegions
	}

	// Check if there's at least one active laboratory that accepts this sample type
	// and can be reached from a serviceable collection point
	locs, err := c.store.GetAllLocations()
	if err != nil {
		return false, c.version, serviceableRegions
	}

	hasLab := false
	for _, l := range locs {
		if !l.Active {
			continue
		}
		if l.Functions.Laboratory == nil || !*l.Functions.Laboratory {
			continue
		}
		for _, acceptedID := range l.AcceptedSampleTypeIDs {
			if acceptedID == sampleTypeID {
				hasLab = true
				break
			}
		}
		if hasLab {
			break
		}
	}

	if !hasLab {
		return false, c.version, serviceableRegions
	}

	// Check connections exist between a serviceable region and a lab
	conns, err := c.store.GetAllConnections()
	if err != nil {
		return true, c.version, serviceableRegions // optimistic
	}

	for _, region := range serviceableRegions {
		for _, l := range locs {
			if !l.Active || l.Functions.Laboratory == nil || !*l.Functions.Laboratory {
				continue
			}
			labAccepts := false
				for _, acceptedID := range l.AcceptedSampleTypeIDs {
				if acceptedID == sampleTypeID {
					labAccepts = true
					break
				}
			}
			if !labAccepts {
				continue
			}
			for _, conn := range conns {
				if conn.Active && conn.FromLocationID == region.LocationID && conn.ToLocationID == l.LocationID {
					travelTime := time.Duration(conn.TravelMinutes+l.HandlingMinutes) * time.Minute
					if time.Now().Add(travelTime).Before(deadline) {
						return true, c.version, serviceableRegions
					}
				}
				// Also check indirect (2-hop)
				if conn.Active && conn.FromLocationID == region.LocationID {
					for _, conn2 := range conns {
						if conn2.Active && conn2.FromLocationID == conn.ToLocationID && conn2.ToLocationID == l.LocationID {
							travelTime := time.Duration(conn.TravelMinutes+conn2.TravelMinutes+l.HandlingMinutes) * time.Minute
							if time.Now().Add(travelTime).Before(deadline) {
								return true, c.version, serviceableRegions
							}
						}
					}
				}
			}
		}
	}

	return true, c.version, serviceableRegions // default to true if we got this far with regions and labs
}

func (c *Calculator) GetRegions() (int, []regionEntry) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.version, c.regions
}

func haversine(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLng := (lng2 - lng1) * math.Pi / 180.0
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*
			math.Sin(dLng/2)*math.Sin(dLng/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}", "path": "/workspace/backend/serviceability/calculator.go"}

{"command": "create", "file_text": "package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"lab-logistics/backend/auth"
	"lab-logistics/backend/models"
	"lab-logistics/backend/serviceability"
	"lab-logistics/backend/store/mongo"
	pgstore "lab-logistics/backend/store/pg"
	redisstore "lab-logistics/backend/store/redis"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"
)

var (
	store    *pgstore.Store
	auditDB  *mongo.AuditStore
	eventsDB *redisstore.EventStore
	svcCalc  *serviceability.Calculator
)

// ----------- Helpers -----------

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]interface{}{
		"error": map[string]string{"code": code, "message": message},
	})
}

func getToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	return r.URL.Query().Get("token")
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token := getToken(r)
		if token == "" {
			writeError(w, 401, "UNAUTHORIZED", "missing authorization")
			return
		}
		payload, err := auth.ValidateToken(token)
		if err != nil {
			writeError(w, 401, "UNAUTHORIZED", err.Error())
			return
		}
		ctx := context.WithValue(r.Context(), "userID", payload.UserID)
		ctx = context.WithValue(ctx, "sessionID", payload.SessionID)
		ctx = context.WithValue(ctx, "activeRole", payload.Role)
		next(w, r.WithContext(ctx))
	}
}

func requireRole(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return authMiddleware(func(w http.ResponseWriter, r *http.Request) {
			role := r.Context().Value("activeRole").(string)
			for _, allowed := range roles {
				if role == allowed {
					next(w, r)
					return
				}
			}
			writeError(w, 403, "FORBIDDEN", "insufficient permissions")
		})
	}
}

func getCurrentRole(r *http.Request) string {
	role := r.Context().Value("activeRole").(string)
	if role == "" {
		return "requester"
	}
	return role
}

func getCurrentUserID(r *http.Request) string {
	return r.Context().Value("userID").(string)
}

func getSessionID(r *http.Request) string {
	return r.Context().Value("sessionID").(string)
}

func logAudit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	entry := models.AuditEntry{
		ActorID:    actorID,
		Role:       role,
		ActorRole:  role,
		Action:     action,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: time.Now(),
		Details:    details,
	}
	if details["auditId"] != nil {
		entry.AuditID = details["auditId"].(string)
	} else {
		entry.AuditID = fmt.Sprintf("%s-%s-%d", entityType, entityID, time.Now().UnixNano())
	}
	auditDB.Insert(ctx, entry)
}

func publishEvent(typ, entityType, entityID string, payload map[string]interface{}) {
	eventsDB.Publish(context.Background(), models.RealtimeEvent{
		Type:       typ,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
	})
}

// ----------- Auth Handlers -----------

func handleLogin(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	userID, hash, fullName, active, err := store.GetUserByUsername(req.Username)
	if err != nil || !active {
		writeError(w, 401, "UNAUTHORIZED", "invalid credentials")
		return
	}

	sum := sha256.Sum256([]byte(req.Password))
	if hex.EncodeToString(sum[:]) != hash {
		writeError(w, 401, "UNAUTHORIZED", "invalid credentials")
		return
	}

	sessionID, err := store.CreateSession(userID)
	if err != nil {
		writeError(w, 500, "INTERNAL_ERROR", err.Error())
		return
	}

	token, err := auth.GenerateSessionToken(userID, sessionID)
	if err != nil {
		writeError(w, 500, "INTERNAL_ERROR", err.Error())
		return
	}

	roles, _ := store.GetUserRoles(userID)
	certs, _ := store.GetUserCerts(userID)

	writeJSON(w, 200, map[string]interface{}{
		"token":     token,
		"sessionId": sessionID,
		"user": map[string]interface{}{
			"userId":   userID,
			"username": req.Username,
			"fullName": fullName,
			"roles":    roles,
			"certifications": certs,
		},
	})

	logAudit(r.Context(), userID, "", "auth.login", "user", userID, true, nil)
}

func handleSwitchRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	userID := getCurrentUserID(r)
	sessionID := getSessionID(r)

	roles, _ := store.GetUserRoles(userID)
	hasRole := false
	for _, rl := range roles {
		if rl["role"] == req.Role {
			hasRole = true
			break
		}
	}
	if !hasRole {
		writeError(w, 403, "FORBIDDEN", "user does not have this role")
		return
	}

	store.SetSessionRole(sessionID, req.Role)
	token, _ := auth.GenerateSessionTokenWithRole(userID, sessionID, req.Role)

	writeJSON(w, 200, map[string]interface{}{
		"token":     token,
		"sessionId": sessionID,
		"role":      req.Role,
	})
}

// ----------- Serviceability -----------

func handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Latitude     float64 `json:"latitude"`
		Longitude    float64 `json:"longitude"`
		SampleTypeID string  `json:"sampleTypeId"`
		Deadline     string  `json:"deadline"`
		RequestID    string  `json:"requestId,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	deadline, err := time.Parse(time.RFC3339, req.Deadline)
	if err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid deadline format")
		return
	}

	serviceable, version, regions := svcCalc.CheckServiceability(req.Latitude, req.Longitude, req.SampleTypeID, deadline)

	result := map[string]interface{}{
		"serviceable":         serviceable,
		"calculationVersion":  version,
		"serviceableRegions":  regions,
	}
	writeJSON(w, 200, result)
}

// ----------- Samples -----------

func handleCreateSample(w http.ResponseWriter, r *http.Request) {
	userID := getCurrentUserID(r)
	var req struct {
		SampleTypeID      string  `json:"sampleTypeId"`
		OriginLatitude    float64 `json:"originLatitude"`
		OriginLongitude   float64 `json:"originLongitude"`
		OriginType        string  `json:"originType"`
		OriginLocationID  string  `json:"originLocationId,omitempty"`
		DeliveryDeadline  string  `json:"deliveryDeadline"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		writeError(w, 400, "BAD_REQUEST", "invalid originType")
		return
	}

	deadline, err := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid deadline format")
		return
	}

	st, err := store.GetSampleType(req.SampleTypeID)
	if err != nil {
		writeError(w, 400, "BAD_REQUEST", "unknown sample type")
		return
	}

	containerType, _ := st["containerType"].(string)
	tempMin, _ := st["temperatureMinC"].(float64)
	tempMax, _ := st["temperatureMaxC"].(float64)

	sampleID, err := store.CreateSample("", userID, req.SampleTypeID, req.OriginLatitude, req.OriginLongitude, req.OriginType, deadline, containerType, tempMin, tempMax)
	if err != nil {
		writeError(w, 500, "INTERNAL_ERROR", err.Error())
		return
	}

	// Check serviceability
	serviceable, _, _ := svcCalc.CheckServiceability(req.OriginLatitude, req.OriginLongitude, req.SampleTypeID, deadline)
	svcStatus := "serviceable"
	if !serviceable {
		svcStatus = "unserviceable"
	}
	store.DB().Exec(`UPDATE samples SET serviceability=$2 WHERE id=$1`, sampleID, svcStatus)

	sample, _ := store.GetSample(sampleID)
	writeJSON(w, 201, sample)

	logAudit(r.Context(), userID, getCurrentRole(r), "sample.create", "sample", sampleID, true, nil)
	publishEvent("sample.created", "sample", sampleID, map[string]interface{}{"sampleId": sampleID})
}

func handleGetSample(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/api/samples/")
	sample, err := store.GetSample(id)
	if err != nil {
		writeError(w, 404, "NOT_FOUND", "sample not found")
		return
	}
	writeJSON(w, 200, sample)
}

func handleListSamples(w http.ResponseWriter, r *http.Request) {
	userID := getCurrentUserID(r)
	role := getCurrentRole(r)

	switch role {
	case "requester":
		samples, _ := store.GetSamplesByRequester(userID)
		items := make([]interface{}, len(samples))
		for i, s := range samples {
			wi := map[string]interface{}{
				"kind":               "sample",
				"sampleId":           s.SampleID,
				"requestId":          s.RequestID,
				"status":             s.State.Status,
				"serviceability":     s.Serviceability,
				"deliveryDeadline":   s.DeliveryDeadline,
				"journeyId":          s.ActiveJourneyID,
				"activeJourneyId":    s.ActiveJourneyID,
				"requesterId":        s.RequesterID,
				"currentHolderId":    s.CurrentHolderID,
				"locationRecordedAt": s.LocationRecordedAt,
				"locationStale":      s.LocationStale,
			}
			if s.LatestLocation != nil {
				wi["latestLocation"] = s.LatestLocation
			}
			items[i] = wi
		}
		if items == nil { items = []interface{}{} }
		writeJSON(w, 200, map[string]interface{}{"workItems": items, "total": len(items)})
	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		assignments, _ := store.GetAssignmentsForWorker(userID)
		items := []interface{}{}
		for _, a := range assignments {
			a["kind"] = a["kind"]
			items = append(items, a)
		}
		if items == nil { items = []interface{}{} }
		writeJSON(w, 200, map[string]interface{}{"workItems": items, "total": len(items)})
	case "dispatcher", "administrator":
		samples, _ := store.GetAllSamples()
		items := make([]interface{}, len(samples))
		for i, s := range samples {
			items[i] = map[string]interface{}{
				"kind":     "sample",
				"sampleId": s.SampleID,
				"status":   s.State.Status,
			}
		}
		if items == nil { items = []interface{}{} }
		writeJSON(w, 200, map[string]interface{}{"workItems": items, "total": len(items)})
	default:
		writeJSON(w, 200, map[string]interface{}{"workItems": []interface{}{}, "total": 0})
	}
}

