func handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/api/locations/")
	var req map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	var name *string
	var lat, lng, covKm *float64
	var hMin *int
	var active *bool
	var fn *models.LocationFunctionStates

	if v, ok := req["name"].(string); ok { name = &v }
	if v, ok := req["latitude"].(float64); ok { lat = &v }
	if v, ok := req["longitude"].(float64); ok { lng = &v }
	if v, ok := req["coverageKm"].(float64); ok { covKm = &v }
	if v, ok := req["handlingMinutes"].(float64); ok { vv := int(v); hMin = &vv }
	if v, ok := req["active"].(bool); ok { active = &v }
	if f, ok := req["functions"].(map[string]interface{}); ok {
		fn = &models.LocationFunctionStates{}
		if v, ok := f["collection_point"].(bool); ok { fn.CollectionPoint = &v }
		if v, ok := f["transfer_point"].(bool); ok { fn.TransferPoint = &v }
		if v, ok := f["hub"].(bool); ok { fn.Hub = &v }
		if v, ok := f["laboratory"].(bool); ok { fn.Laboratory = &v }
	}

	if err := store.UpdateLocation(id, name, lat, lng, covKm, hMin, active, fn); err != nil {
		writeError(w, 404, "NOT_FOUND", "location not found")
		return
	}
	go svcCalc.Compute()

	loc, _ := store.GetLocation(id)
	writeJSON(w, 200, loc)
	logAudit(r.Context(), getCurrentUserID(r), getCurrentRole(r), "location.update", "location", id, true, nil)
}

