// ----------- Register pre-sealed sample -----------

func handleRegisterSample(w http.ResponseWriter, r *http.Request) {
	userID := getCurrentUserID(r)
	var req struct {
		SampleTypeID     string  `json:"sampleTypeId"`
		OriginLatitude   float64 `json:"originLatitude"`
		OriginLongitude  float64 `json:"originLongitude"`
		OriginLocationID string  `json:"originLocationId"`
		DeliveryDeadline string  `json:"deliveryDeadline"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	if req.OriginLocationID == "" {
		writeError(w, 400, "BAD_REQUEST", "originLocationId required for pre-sealed samples")
		return
	}

	deadline, _ := time.Parse(time.RFC3339, req.DeliveryDeadline)
	st, err := store.GetSampleType(req.SampleTypeID)
	if err != nil {
		writeError(w, 400, "BAD_REQUEST", "unknown sample type")
		return
	}
	containerType, _ := st["containerType"].(string)
	tempMin, _ := st["temperatureMinC"].(float64)
	tempMax, _ := st["temperatureMaxC"].(float64)

	sampleID, err := store.CreateSample("", userID, req.SampleTypeID, req.OriginLatitude, req.OriginLongitude, "node", deadline, containerType, tempMin, tempMax)
	if err != nil {
		writeError(w, 500, "INTERNAL_ERROR", err.Error())
		return
	}

	store.SetSampleSealed(sampleID)
	store.SetSampleHolder(sampleID, userID)
	store.UpdateSampleStatus(sampleID, "sealed")
	store.SetSampleLocation(sampleID, req.OriginLatitude, req.OriginLongitude)

	sample, _ := store.GetSample(sampleID)
	writeJSON(w, 201, sample)
	logAudit(r.Context(), userID, getCurrentRole(r), "sample.register", "sample", sampleID, true, nil)
	publishEvent("sample.registered", "sample", sampleID, nil)
}

// ----------- Record location -----------

func handleRecordLocation(w http.ResponseWriter, r *http.Request) {
	userID := getCurrentUserID(r)
	var req struct {
		Latitude  float64 `json:"latitude"`
		Longitude float64 `json:"longitude"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}

	// Store in a simple way - update all samples held by this user
	store.DB().Exec(`UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=now(), location_stale=false WHERE current_holder_id=$1`, userID, req.Latitude, req.Longitude)

	writeJSON(w, 200, map[string]interface{}{"status": "ok"})
}

// ----------- Serviceability regions -----------

func handleServiceabilityRegions(w http.ResponseWriter, r *http.Request) {
	version, regions := svcCalc.GetRegions()
	writeJSON(w, 200, map[string]interface{}{
		"calculationVersion": version,
		"regions":            regions,
	})
}

// ----------- Journey planner (create route) -----------

func handleCreateJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID  string `json:"sampleId"`
		RouteMode string `json:"routeMode"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid body")
		return
	}
	if req.RouteMode == "" {
		req.RouteMode = "direct"
	}

	sample, err := store.GetSample(req.SampleID)
	if err != nil {
		writeError(w, 404, "NOT_FOUND", "sample not found")
		return
	}

	journeyID, err := store.CreateJourney(req.SampleID, req.RouteMode)
	if err != nil {
		writeError(w, 500, "INTERNAL_ERROR", err.Error())
		return
	}

	// Create a basic journey with stops
	store.AddJourneyStop(journeyID, "", "pickup", 1, time.Now().Add(30*time.Minute), sample.Origin.Latitude, sample.Origin.Longitude)

	// Add delivery stop if target lab set
	if sample.TargetLaboratoryID != "" {
		lab, err := store.GetLocation(sample.TargetLaboratoryID)
		if err == nil {
			store.AddJourneyStop(journeyID, sample.TargetLaboratoryID, "delivery", 2, time.Now().Add(2*time.Hour), lab.Coordinate.Latitude, lab.Coordinate.Longitude)
		}
	}

	store.UpdateSampleStatus(req.SampleID, "planned")
	store.DB().Exec(`UPDATE samples SET active_journey_id=(SELECT id FROM journeys WHERE id=$1 LIMIT 1) WHERE id=$2`, journeyID, req.SampleID)

	j, _ := store.GetJourney(journeyID)
	writeJSON(w, 201, j)
	logAudit(r.Context(), getCurrentUserID(r), getCurrentRole(r), "journey.create", "journey", journeyID, true, nil)
	publishEvent("journey.created", "journey", journeyID, nil)
}

// ----------- Mark sample collected -----------

func handleCollectSample(w http.ResponseWriter, r *http.Request) {
	userID := getCurrentUserID(r)
	id := strings.TrimPrefix(r.URL.Path, "/api/samples/")
	id = strings.TrimSuffix(id, "/collect")

	store.SetSampleSealed(id)
	store.SetSampleHolder(id, userID)
	store.UpdateSampleStatus(id, "collected")

	sample, _ := store.GetSample(id)
	writeJSON(w, 200, sample)
	logAudit(r.Context(), userID, getCurrentRole(r), "sample.collect", "sample", id, true, nil)
	publishEvent("sample.collected", "sample", id, nil)
}

// ----------- Ready -----------

func handleReady(w http.ResponseWriter, r *http.Request) {
	if err := store.DB().Ping(); err != nil {
		writeJSON(w, 503, map[string]string{"status": "not_ready"})
		return
	}
	writeJSON(w, 200, map[string]string{"status": "ready"})
}

// ----------- Main -----------

func main() {
	pgHost := os.Getenv("PGHOST")
	if pgHost == "" {
		pgHost = "127.0.0.1"
	}
	pgPort, _ := strconv.Atoi(os.Getenv("PGPORT"))
	if pgPort == 0 {
		pgPort = 15432
	}
	pgUser := os.Getenv("PGUSER")
	if pgUser == "" {
		pgUser = "agent"
	}
	pgPass := os.Getenv("PGPASSWORD")
	pgDB := os.Getenv("PGDATABASE")
	if pgDB == "" {
		pgDB = "agent"
	}

	mongoURI := os.Getenv("MONGO_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017"
	}
	redisAddr := os.Getenv("REDIS_ADDR")
	if redisAddr == "" {
		redisAddr = "127.0.0.1:6379"
	}

	var err error
	store, err = pgstore.New(pgHost, pgPort, pgUser, pgPass, pgDB)
	if err != nil {
		log.Fatalf("PostgreSQL connection failed: %v", err)
	}
	defer store.Close()

	log.Println("PostgreSQL connected")

	auditDB, err = mongo.New(mongoURI)
	if err != nil {
		log.Fatalf("MongoDB connection failed: %v", err)
	}
	defer auditDB.Close(context.Background())
	auditDB.Init(context.Background())
	log.Println("MongoDB connected")

	eventsDB, err = redisstore.New(redisAddr)
	if err != nil {
		log.Fatalf("Redis connection failed: %v", err)
	}
	defer eventsDB.Close()
	eventsDB.Init(context.Background())
	log.Println("Redis connected")

	svcCalc = serviceability.New(store)
	svcCalc.Compute()
	log.Println("Serviceability computed")

	mux := http.NewServeMux()

	// Auth
	mux.HandleFunc("POST /api/auth/login", handleLogin)
	mux.HandleFunc("POST /api/auth/switch-role", authMiddleware(handleSwitchRole))

	// Serviceability
	mux.HandleFunc("POST /api/serviceability", authMiddleware(handleCheckServiceability))
	mux.HandleFunc("GET /api/serviceability-regions", authMiddleware(handleServiceabilityRegions))

	// Samples
	mux.HandleFunc("POST /api/samples", requireRole("requester", "collection_professional", "node_handler", "laboratory_team", "administrator", "dispatcher")(handleCreateSample))
	mux.HandleFunc("GET /api/samples", authMiddleware(handleListSamples))
	mux.HandleFunc("GET /api/samples/", authMiddleware(func(w http.ResponseWriter, r *http.Request) {
		path := strings.TrimPrefix(r.URL.Path, "/api/samples/")
		if strings.HasSuffix(path, "/lifecycle") {
			handleSampleLifecycle(w, r)
		} else if strings.HasSuffix(path, "/collect") {
			handleCollectSample(w, r)
		} else {
			handleGetSample(w, r)
		}
	}))
	mux.HandleFunc("POST /api/samples/register", requireRole("collection_professional", "delivery_partner", "node_handler", "laboratory_team")(handleRegisterSample))

	// Journeys
	mux.HandleFunc("POST /api/journeys", requireRole("dispatcher", "administrator")(handleCreateJourney))
	mux.HandleFunc("GET /api/journeys/", authMiddleware(handleGetJourney))
	mux.HandleFunc("POST /api/journeys/", authMiddleware(func(w http.ResponseWriter, r *http.Request) {
		path := strings.TrimPrefix(r.URL.Path, "/api/journeys/")
		if strings.HasSuffix(path, "/cancel") {
			handleCancelJourney(w, r)
		} else {
			writeError(w, 404, "NOT_FOUND", "not found")
		}
	}))

	// Assignments
	mux.HandleFunc("POST /api/assignments/", authMiddleware(func(w http.ResponseWriter, r *http.Request) {
		path := strings.TrimPrefix(r.URL.Path, "/api/assignments/")
		if strings.HasSuffix(path, "/accept") {
			handleAcceptAssignment(w, r)
		} else if strings.HasSuffix(path, "/decline") {
			handleDeclineAssignment(w, r)
		} else {
			writeError(w, 404, "NOT_FOUND", "not found")
		}
	}))

	// Locations
	mux.HandleFunc("GET /api/locations", authMiddleware(handleListLocations))
	mux.HandleFunc("POST /api/locations", requireRole("administrator")(handleCreateLocation))
	mux.HandleFunc("GET /api/locations/", authMiddleware(handleGetLocation))
	mux.HandleFunc("PUT /api/locations/", requireRole("administrator")(handleUpdateLocation))
	mux.HandleFunc("POST /api/locations/", authMiddleware(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasSuffix(r.URL.Path, "/active") {
			handleSetLocationActive(w, r)
		} else {
			writeError(w, 404, "NOT_FOUND", "not found")
		}
	}))

	// Connections
	mux.HandleFunc("GET /api/connections", authMiddleware(handleListConnections))
	mux.HandleFunc("POST /api/connections", requireRole("administrator")(handleCreateConnection))
	mux.HandleFunc("POST /api/connections/", authMiddleware(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasSuffix(r.URL.Path, "/active") {
			handleSetConnectionActive(w, r)
		} else {
			writeError(w, 404, "NOT_FOUND", "not found")
		}
	}))

	// Sample types
	mux.HandleFunc("GET /api/sample-types", authMiddleware(handleListSampleTypes))
	mux.HandleFunc("POST /api/sample-types", requireRole("administrator")(handleCreateSampleType))
	mux.HandleFunc("PUT /api/sample-types/", requireRole("administrator")(handleUpdateSampleType))

	// Users
	mux.HandleFunc("GET /api/users", requireRole("administrator")(handleListUsers))
	mux.HandleFunc("GET /api/users/", requireRole("administrator")(handleGetUser))
	mux.HandleFunc("POST /api/users/", requireRole("administrator")(func(w http.ResponseWriter, r *http.Request) {
		path := strings.TrimPrefix(r.URL.Path, "/api/users/")
		if strings.HasSuffix(path, "/roles") {
			handleAddUserRole(w, r)
		} else if strings.HasSuffix(path, "/certifications") {
			handleAddCertification(w, r)
		} else if strings.HasSuffix(path, "/active") {
			handleSetUserActive(w, r)
		} else {
			writeError(w, 404, "NOT_FOUND", "not found")
		}
	}))
	mux.HandleFunc("DELETE /api/users/", requireRole("administrator")(handleRemoveUserRole))

	// Workers
	mux.HandleFunc("GET /api/workers", requireRole("dispatcher", "administrator")(handleListWorkers))

	// Capacity
	mux.HandleFunc("POST /api/capacity", requireRole("administrator")(handleConfigureCapacity))

	// Handoff
	mux.HandleFunc("POST /api/handoffs", authMiddleware(handleHandoff))
	mux.HandleFunc("POST /api/handoffs/", authMiddleware(handleConfirmHandoff))

	// Checkpoint
	mux.HandleFunc("POST /api/checkpoints", authMiddleware(handleCheckpoint))

	// Audit
	mux.HandleFunc("GET /api/audit", requireRole("dispatcher", "administrator")(handleAuditSearch))

	// Events
	mux.HandleFunc("GET /api/events", authMiddleware(handleEvents))

	// Map
	mux.HandleFunc("GET /api/map-data", authMiddleware(handleMapData))

	// Location recording
	mux.HandleFunc("POST /api/location", authMiddleware(handleRecordLocation))

	// Ready
	mux.HandleFunc("GET /api/ready", handleReady)
	mux.HandleFunc("GET /ready", handleReady)

	// CORS
	corsHandler := func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
		if r.Method == "OPTIONS" {
			w.WriteHeader(200)
			return
		}
		mux.ServeHTTP(w, r)
	}

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	// Create admin user if needed
	adminUser := os.Getenv("ADMIN_USERNAME")
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminUser != "" && adminPass != "" {
		_, _, _, _, err := store.GetUserByUsername(adminUser)
		if err != nil {
			sum := sha256.Sum256([]byte(adminPass))
			hash := hex.EncodeToString(sum[:])
			userID, err := store.CreateUser(adminUser, hash, "Administrator")
			if err == nil {
				store.AddUserRole(userID, "administrator", nil, nil)
				log.Printf("Created admin user: %s", adminUser)
			}
		}
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, http.HandlerFunc(corsHandler)))
}", "path": "/workspace/backend/main.go"}

