func (s *Store) GetSampleLifecycle(id string) (*models.SampleLifecycle, error) {
	ss, err := s.GetSample(id)
	if err != nil {
		return nil, err
	}
	sl := &models.SampleLifecycle{
		SampleID:     ss.SampleID,
		Status:       ss.State.Status,
		Sealed:       ss.Sealed,
		Timeline:     ss.Timeline,
		LocationStale: ss.LocationStale,
	}

	// Get completed leg IDs
	rows, _ := s.db.Query(`SELECT id FROM journey_legs WHERE sample_id=$1 AND status='completed'`, id)
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var lid string
			rows.Scan(&lid)
			sl.CompletedLegIDs = append(sl.CompletedLegIDs, lid)
		}
	}
	if sl.CompletedLegIDs == nil {
		sl.CompletedLegIDs = []string{}
	}

	// Get active replacement plan IDs
	rrows, _ := s.db.Query(`SELECT id FROM journeys WHERE sample_id=$1 AND active=true AND parent_journey_id IS NOT NULL`, id)
	if rrows != nil {
		defer rrows.Close()
		for rrows.Next() {
			var jid string
			rrows.Scan(&jid)
			sl.ActiveReplacementPlanIDs = append(sl.ActiveReplacementPlanIDs, jid)
		}
	}
	if sl.ActiveReplacementPlanIDs == nil {
		sl.ActiveReplacementPlanIDs = []string{}
	}

	sl.ActiveJourneyID = ss.ActiveJourneyID
	sl.CurrentHolderID = ss.CurrentHolderID
	sl.TargetLaboratoryID = ss.TargetLaboratoryID
	sl.LatestLocation = ss.LatestLocation
	sl.LocationRecordedAt = ss.LocationRecordedAt

	// Pending handoff
	var hid string
	s.db.QueryRow(`SELECT id FROM handoffs WHERE sample_id=$1 AND completed_at IS NULL LIMIT 1`, id).Scan(&hid)
	if hid != "" {
		sl.PendingHandoffID = hid
		sl.PendingHandoff = map[string]interface{}{"handoffId": hid}
	}

	return sl, nil
}

func (s *Store) GetJourneyPlan(id string, userID string, isWorker bool) (*models.JourneyPlan, *models.WorkerJourneyPlan, *models.RequesterJourneyPlan, error) {
	var jp models.JourneyPlan
	var parentID sql.NullString
	var estDel sql.NullTime
	var totalCost sql.NullFloat64
	var capUsed, capAvail sql.NullInt64
	var replStatus sql.NullString
	var replID sql.NullString
	var collAssID, firstTrans, middleTrans, finalTrans sql.NullString

	err := s.db.QueryRow(`SELECT id, parent_journey_id, plan_version, route_mode, status,
		estimated_delivery_at, total_cost_units, valid, replan_status, replacement_journey_id
		FROM journeys WHERE id=$1`, id).Scan(
		&jp.JourneyID, &parentID, &jp.PlanVersion, &jp.RouteMode, &jp.Status,
		&estDel, &totalCost, &jp.Valid, &replStatus, &replID)
	if err != nil {
		return nil, nil, nil, err
	}
	if parentID.Valid {
		jp.ParentJourneyID = parentID.String
	}
	if estDel.Valid {
		jp.EstimatedDeliveryAt = &estDel.Time
	}
	if totalCost.Valid {
		jp.TotalCostUnits = totalCost.Float64
	}
	if capUsed.Valid {
		jp.CapacityUsed = int(capUsed.Int64)
	}
	if capAvail.Valid {
		jp.CapacityAvailable = int(capAvail.Int64)
	}
	if replStatus.Valid {
		jp.ReplanStatus = replStatus.String
	}

	// Sample IDs
	srows, _ := s.db.Query(`SELECT sample_id FROM journeys WHERE id=$1 OR parent_journey_id=$1`, id)
	if srows != nil {
		defer srows.Close()
		for srows.Next() {
			var sid string
			srows.Scan(&sid)
			jp.SampleIDs = append(jp.SampleIDs, sid)
		}
	}
	if jp.SampleIDs == nil {
		jp.SampleIDs = []string{}
	}

	// Legs
	lrows, _ := s.db.Query(`SELECT id, assignment_id, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM journey_legs WHERE journey_id=$1 ORDER BY sequence ASC`, id)
	if lrows != nil {
		defer lrows.Close()
		for lrows.Next() {
			var leg models.JourneyLeg
			var asgnID, fl, tl, wid, sid sql.NullString
			lrows.Scan(&leg.AssignmentID, &asgnID, &leg.Sequence, &leg.Status, &fl, &tl, &wid, &sid)
			if asgnID.Valid {
				jp.AssignedWorkerIDs = append(jp.AssignedWorkerIDs, asgnID.String)
			}
			if fl.Valid {
				leg.FromLocationID = fl.String
			}
			if tl.Valid {
				leg.ToLocationID = tl.String
			}
			if wid.Valid {
				leg.WorkerID = wid.String
			}
			if sid.Valid {
				leg.SampleID = sid.String
			}
			jp.Legs = append(jp.Legs, leg)
		}
	}
	if jp.Legs == nil {
		jp.Legs = []models.JourneyLeg{}
	}

	// Stops
	strows, _ := s.db.Query(`SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at FROM journey_stops WHERE journey_id=$1 ORDER BY sequence ASC`, id)
	if strows != nil {
		defer strows.Close()
		for strows.Next() {
			var stop models.JourneyStop
			var locID sql.NullString
			var estAt sql.NullTime
			var lat, lng sql.NullFloat64
			var compAt sql.NullTime
			strows.Scan(&stop.StopID, &locID, &stop.StopType, &stop.Sequence, &estAt, &stop.DwellMinutes, &lat, &lng, &compAt)
			if locID.Valid {
				stop.LocationID = locID.String
			}
			if estAt.Valid {
				stop.EstimatedAt = estAt.Time
			}
			if lat.Valid && lng.Valid {
				stop.Coordinate = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
			}
			if compAt.Valid {
				stop.CompletedAt = &compAt.Time
			}
			jp.OrderedStops = append(jp.OrderedStops, stop)
		}
	}
	if jp.OrderedStops == nil {
		jp.OrderedStops = []models.JourneyStop{}
	}

	// Build worker and requester views
	wjp := &models.WorkerJourneyPlan{
		JourneyID:           jp.JourneyID,
		ParentJourneyID:     jp.ParentJourneyID,
		PlanVersion:         jp.PlanVersion,
		RouteMode:           jp.RouteMode,
		Status:              jp.Status,
		EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
		Scope:               "assigned_legs",
		AssignmentIDs:       jp.AssignedWorkerIDs,
		SampleIDs:           jp.SampleIDs,
		Legs:                jp.Legs,
		OrderedStops:        jp.OrderedStops,
	}
	if wjp.AssignmentIDs == nil {
		wjp.AssignmentIDs = []string{}
	}

	rjp := &models.RequesterJourneyPlan{
		JourneyID:           jp.JourneyID,
		ParentJourneyID:     jp.ParentJourneyID,
		PlanVersion:         jp.PlanVersion,
		RouteMode:           jp.RouteMode,
		Status:              jp.Status,
		EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
		TotalCostUnits:      jp.TotalCostUnits,
		SampleIDs:           jp.SampleIDs,
		OrderedStops:        jp.OrderedStops,
		Legs:                make([]interface{}, len(jp.Legs)),
	}
	for i, l := range jp.Legs {
		rjp.Legs[i] = l
	}

	if isWorker {
		return &jp, wjp, nil, nil
	}
	return &jp, nil, rjp, nil
}

func (s *Store) ListRoleWork(userID, role, statusFilter string) ([]interface{}, error) {
	var items []interface{}

	switch role {
	case "requester":
		rows, err := s.db.Query(`SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, userID)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var id string
			rows.Scan(&id)
			ss, _ := s.GetSample(id)
			if ss == nil {
				continue
			}
			wi := models.SampleWorkItem{
				Kind:       "sample",
				SampleID:   ss.SampleID,
				RequestID:  ss.RequestID,
				Status:     ss.State.Status,
				History:    ss.Timeline,
				LocationStale: ss.LocationStale,
			}
			if ss.DeliveryDeadline.Unix() > 0 {
				wi.DeliveryDeadline = &ss.DeliveryDeadline
			}
			if ss.RequestedAt.Unix() > 0 {
				wi.RequestedAt = &ss.RequestedAt
			}
			if ss.LocationRecordedAt != nil {
				wi.LocationRecordedAt = ss.LocationRecordedAt
			}
			items = append(items, wi)
		}

	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		rows, err := s.db.Query(`SELECT id, kind, sample_id, journey_id, status, offer_expires_at FROM assignments WHERE worker_id=$1 ORDER BY created_at DESC`, userID)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var id, kind, sampleID, status string
			var journeyID sql.NullString
			var offerExp sql.NullTime
			rows.Scan(&id, &kind, &sampleID, &journeyID, &status, &offerExp)

			wi := models.AssignmentWorkItem{
				Kind:         kind,
				AssignmentID: id,
				SampleID:     sampleID,
				Status:       status,
			}
			if journeyID.Valid {
				wi.JourneyID = journeyID.String
			}
			if offerExp.Valid {
				wi.OfferExpiresAt = &offerExp.Time
			}
			// Get timeline for assignment
			trows, _ := s.db.Query(`SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details FROM timeline WHERE entity_id=$1 ORDER BY event_id ASC`, id)
			if trows != nil {
				defer trows.Close()
				for trows.Next() {
					var te models.TimelineEntry
					var detJSON string
					trows.Scan(&te.EventID, &te.Action, &te.ActorID, &te.Role, &te.EntityType, &te.EntityID, &te.Success, &te.OccurredAt, &detJSON)
					if detJSON != "" {
						json.Unmarshal([]byte(detJSON), &te.Details)
					}
					if te.Details == nil {
						te.Details = map[string]interface{}{}
					}
					wi.History = append(wi.History, te)
				}
			}
			if wi.History == nil {
				wi.History = []models.TimelineEntry{}
			}
			items = append(items, wi)
		}

	case "dispatcher", "administrator":
		// Journeys
		jrows, _ := s.db.Query(`SELECT id FROM journeys ORDER BY created_at DESC LIMIT 100`)
		if jrows != nil {
			defer jrows.Close()
			for jrows.Next() {
				var jid string
				jrows.Scan(&jid)
				jwi := models.JourneyWorkItem{
					Kind: "journey",
				}
				s.db.QueryRow(`SELECT id, status, route_mode, plan_version, estimated_delivery_at FROM journeys WHERE id=$1`, jid).Scan(&jwi.JourneyID, &jwi.Status, &jwi.RouteMode, &jwi.PlanVersion, &jwi.EstimatedDeliveryAt)
				srows, _ := s.db.Query(`SELECT sample_id FROM journeys WHERE id=$1 OR parent_journey_id=$1`, jid)
				if srows != nil {
					defer srows.Close()
					for srows.Next() {
						var sid string
						srows.Scan(&sid)
						jwi.SampleIDs = append(jwi.SampleIDs, sid)
					}
				}
				if jwi.SampleIDs == nil {
					jwi.SampleIDs = []string{}
				}
				var count int
				s.db.QueryRow(`SELECT COUNT(*) FROM journey_legs WHERE journey_id=$1`, jid).Scan(&count)
				jwi.AssignmentCount = count
				jwi.History = []models.TimelineEntry{}
				items = append(items, jwi)
			}
		}
	}

	if items == nil {
		items = []interface{}{}
	}
	return items, nil
}

func (s *Store) GetAllJourneys() ([]map[string]interface{}, error) {
	rows, err := s.db.Query(`SELECT id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, active FROM journeys ORDER BY created_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var results []map[string]interface{}
	for rows.Next() {
		var id, routeMode, status string
		var parentID sql.NullString
		var planVer int
		var estDel sql.NullTime
		var active bool
		rows.Scan(&id, &parentID, &planVer, &routeMode, &status, &estDel, &active)
		m := map[string]interface{}{
			"journeyId":   id,
			"routeMode":   routeMode,
			"status":      status,
			"planVersion": planVer,
			"active":      active,
		}
		if parentID.Valid {
			m["parentJourneyId"] = parentID.String
		}
		if estDel.Valid {
			m["estimatedDeliveryAt"] = estDel.Time
		}
		results = append(results, m)
	}
	return results, nil
}

func (s *Store) GetOperationsState() (map[string]interface{}, error) {
	state := map[string]interface{}{
		"samples":     []interface{}{},
		"workers":     []interface{}{},
		"locations":   []interface{}{},
		"connections": []interface{}{},
		"routes":      []interface{}{},
		"handoffs":    []interface{}{},
		"delays":      []interface{}{},
		"exceptions":  []interface{}{},
	}

	// Samples
	srows, _ := s.db.Query(`SELECT id, request_id, status, requester_id, origin_latitude, origin_longitude, delivery_deadline, current_holder_id, latest_lat, latest_lng, location_recorded_at, location_stale FROM samples ORDER BY created_at DESC LIMIT 200`)
	if srows != nil {
		defer srows.Close()
		for srows.Next() {
			var id, reqID, status, reqerID string
			var lat, lng float64
			var dd, lra sql.NullTime
			var holderID sql.NullString
			var llat, llng sql.NullFloat64
			var stale bool
			srows.Scan(&id, &reqID, &status, &reqerID, &lat, &lng, &dd, &holderID, &llat, &llng, &lra, &stale)
			m := map[string]interface{}{
				"sampleId":              id,
				"status":                status,
				"locationStale":         stale,
				"origin":                models.Coordinate{Latitude: lat, Longitude: lng},
			}
			if reqID != "" {
				m["requestId"] = reqID
			}
			if dd.Valid {
				m["deliveryDeadline"] = dd.Time
			}
			if llat.Valid && llng.Valid {
				m["latestLocation"] = models.Coordinate{Latitude: llat.Float64, Longitude: llng.Float64}
			}
			if lra.Valid {
				m["locationRecordedAt"] = lra.Time
			}
			if holderID.Valid {
				m["currentHolderId"] = holderID.String
			}
			// active journey
			var jid sql.NullString
			s.db.QueryRow(`SELECT id FROM journeys WHERE sample_id=$1 AND active=true LIMIT 1`, id).Scan(&jid)
			if jid.Valid {
				m["activeJourneyId"] = jid.String
			}
			samples := state["samples"].([]interface{})
			state["samples"] = append(samples, m)
		}
	}

	// Workers
	wrows, _ := s.db.Query(`SELECT u.id, u.full_name FROM users u JOIN user_roles ur ON u.id=ur.user_id WHERE u.active=true AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')`)
	if wrows != nil {
		defer wrows.Close()
		for wrows.Next() {
			var id, name string
			wrows.Scan(&id, &name)
			var count int
			s.db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('offered','accepted','in_progress')`, id).Scan(&count)
			w := map[string]interface{}{
				"workerId":        id,
				"fullName":        name,
				"available":       count == 0,
				"status":          "available",
				"capacityUnits":   10,
				"assignmentCount": count,
				"locationStale":   true,
			}
			if count > 0 {
				w["available"] = false
				w["status"] = "unavailable"
			}
			workers := state["workers"].([]interface{})
			state["workers"] = append(workers, w)
		}
	}

	// Locations
	lrows, _ := s.db.Query(`SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations`)
	if lrows != nil {
		defer lrows.Close()
		for lrows.Next() {
			var id, name string
			var lat, lng, covKm float64
			var handlingMin int
			var active, cp, tp, hub, lab bool
			var cap, res, cooledCap, cooledRes int
			lrows.Scan(&id, &name, &lat, &lng, &covKm, &handlingMin, &active, &cp, &tp, &hub, &lab, &cap, &res, &cooledCap, &cooledRes)
			ol := models.OperationsLocation{
				ID:              id,
				LocationID:      id,
				Name:            name,
				Coordinate:      models.Coordinate{Latitude: lat, Longitude: lng},
				Active:          active,
				CoverageKm:      covKm,
				HandlingMinutes: handlingMin,
				Functions: models.LocationFunctionStates{
					CollectionPoint: &cp,
					TransferPoint:   &tp,
					Hub:             &hub,
					Laboratory:      &lab,
				},
				Capacity: &models.Capacity{
					CapacityUnits:       cap,
					ReservedUnits:       res,
					AvailableUnits:      cap - res,
					CooledCapacityUnits: cooledCap,
					CooledReservedUnits: cooledRes,
					CooledAvailableUnits: cooledCap - cooledRes,
				},
			}
			// Accepted sample types
			arows, _ := s.db.Query(`SELECT sample_type_id FROM location_accepted_sample_types WHERE location_id=$1`, id)
			if arows != nil {
				defer arows.Close()
				for arows.Next() {
					var st string
					arows.Scan(&st)
					ol.AcceptedSampleTypeIDs = append(ol.AcceptedSampleTypeIDs, st)
				}
			}
			locs := state["locations"].([]interface{})
			state["locations"] = append(locs, ol)
		}
	}

	// Connections
	crows, _ := s.db.Query(`SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections`)
	if crows != nil {
		defer crows.Close()
		for crows.Next() {
			var id, fl, tl string
			var travelMin int
			var cost float64
			var cooled, active bool
			var cap, res, cCap, cRes int
			crows.Scan(&id, &fl, &tl, &travelMin, &cost, &cooled, &active, &cap, &res, &cCap, &cRes)
			oc := models.OperationsConnection{
				ID:             id,
				ConnectionID:   id,
				FromLocationID: fl,
				ToLocationID:   tl,
				TravelMinutes:  travelMin,
				CostUnits:      cost,
				Cooled:         cooled,
				Active:         active,
				Capacity: &models.Capacity{
					CapacityUnits:       cap,
					ReservedUnits:       res,
					AvailableUnits:      cap - res,
					CooledCapacityUnits: cCap,
					CooledReservedUnits: cRes,
					CooledAvailableUnits: cCap - cRes,
				},
			}
			conns := state["connections"].([]interface{})
			state["connections"] = append(conns, oc)
		}
	}

	state["assignmentCountSpread"] = 0
	state["ineligibleAssignmentCount"] = 0
	return state, nil
}

func (s *Store) CancelJourney(journeyID string, reason string) error {
	_, err := s.db.Exec(`UPDATE journeys SET status='cancelled', active=false, replan_status='not_required' WHERE id=$1`, journeyID)
	if err != nil {
		return err
	}
	// Cancel all associated assignments
	_, err = s.db.Exec(`UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('offered','accepted')`, journeyID)
	return err
}

func (s *Store) SplitJourney(journeyID string, sampleIDs []string) (string, error) {
	// Get original journey details
	var planVer int
	var routeMode string
	s.db.QueryRow(`SELECT plan_version, route_mode FROM journeys WHERE id=$1`, journeyID).Scan(&planVer, &routeMode)

	// Create new journey from original
	newID := uuid.New().String()
	_, err := s.db.Exec(`INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, active) VALUES ($1, $2, 1, $3, 'planned', true)`, newID, journeyID, routeMode)
	if err != nil {
		return "", err
	}

	// Move samples to new journey
	for _, sid := range sampleIDs {
		s.db.Exec(`INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, active, sample_id) VALUES ($1, $2, 1, $3, 'planned', true, $4)`,
			uuid.New().String(), newID, routeMode, sid)
	}

	// Update original journey version
	s.db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE id=$1`, journeyID)
	return newID, nil
}

func (s *Store) MergeJourneys(targetID string, sourceIDs []string) error {
	for _, sid := range sourceIDs {
		// Move samples from source to target
		s.db.Exec(`UPDATE journeys SET parent_journey_id=$1 WHERE parent_journey_id=$2`, targetID, sid)
		s.db.Exec(`UPDATE journeys SET status='merged', active=false WHERE id=$1`, sid)
	}
	s.db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE id=$1`, targetID)
	return nil
}

func (s *Store) SetConnectionStatus(connID string, active bool) error {
	_, err := s.db.Exec(`UPDATE connections SET active=$2 WHERE id=$1`, connID, active)
	return err
}

func (s *Store) SetLocationFunctionStatus(locID, function string, active bool) error {
	switch function {
	case "collection_point":
		_, err := s.db.Exec(`UPDATE locations SET fn_collection_point=$2 WHERE id=$1`, locID, active)
		return err
	case "transfer_point":
		_, err := s.db.Exec(`UPDATE locations SET fn_transfer_point=$2 WHERE id=$1`, locID, active)
		return err
	case "hub":
		_, err := s.db.Exec(`UPDATE locations SET fn_hub=$2 WHERE id=$1`, locID, active)
		return err
	case "laboratory":
		_, err := s.db.Exec(`UPDATE locations SET fn_laboratory=$2 WHERE id=$1`, locID, active)
		return err
	}
	return fmt.Errorf("unknown function: %s", function)
}

func (s *Store) ReportDisruption(resourceType, resourceID, reason string) error {
	if resourceType == "location" {
		s.db.Exec(`UPDATE locations SET active=false WHERE id=$1`, resourceID)
	} else if resourceType == "connection" {
		s.db.Exec(`UPDATE connections SET active=false WHERE id=$1`, resourceID)
	} else if resourceType == "worker" {
		// Mark worker assignments as problematic
	}
	return nil
}

func (s *Store) GetUserByID(userID string) (map[string]interface{}, error) {
	var username, fullName string
	var active bool
	err := s.db.QueryRow(`SELECT username, full_name, active FROM users WHERE id=$1`, userID).Scan(&username, &fullName, &active)
	if err != nil {
		return nil, err
	}
	m := map[string]interface{}{
		"userId":   userID,
		"username": username,
		"fullName": fullName,
		"active":   active,
		"roles":    []interface{}{},
	}

	// Roles
	rrows, _ := s.db.Query(`SELECT role, node_id, laboratory_id FROM user_roles WHERE user_id=$1`, userID)
	if rrows != nil {
		defer rrows.Close()
		for rrows.Next() {
			var role string
			var nodeID, labID sql.NullString
			rrows.Scan(&role, &nodeID, &labID)
			r := map[string]interface{}{"role": role}
			if nodeID.Valid {
				r["nodeId"] = nodeID.String
			}
			if labID.Valid {
				r["laboratoryId"] = labID.String
			}
			roles := m["roles"].([]interface{})
			m["roles"] = append(roles, r)
		}
	}

	// Certifications
	crows, _ := s.db.Query(`SELECT code, active, expires_at FROM certifications WHERE user_id=$1`, userID)
	if crows != nil {
		defer crows.Close()
		var certs []interface{}
		for crows.Next() {
			var code string
			var active bool
			var expiresAt sql.NullTime
			crows.Scan(&code, &active, &expiresAt)
			c := map[string]interface{}{"code": code, "active": active}
			if expiresAt.Valid {
				c["expiresAt"] = expiresAt.Time
			}
			certs = append(certs, c)
		}
		m["certifications"] = certs
	}
	return m, nil
}

func (s *Store) ListUsers() ([]map[string]interface{}, error) {
	rows, err := s.db.Query(`SELECT id, username, full_name, active FROM users ORDER BY created_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var users []map[string]interface{}
	for rows.Next() {
		var id, username, fullName string
		var active bool
		rows.Scan(&id, &username, &fullName, &active)
		u := map[string]interface{}{
			"userId":   id,
			"username": username,
			"fullName": fullName,
			"active":   active,
		}
		users = append(users, u)
	}
	return users, nil
}

func (s *Store) CreateUser(username, password, fullName, email string, roles []string, assignedLocationID string) (string, error) {
	hash := hashPassword(password)
	id := uuid.New().String()
	_, err := s.db.Exec(`INSERT INTO users (id, username, password_hash, full_name) VALUES ($1, $2, $3, $4)`, id, username, hash, fullName)
	if err != nil {
		return "", err
	}
	for _, role := range roles {
		s.db.Exec(`INSERT INTO user_roles (user_id, role, node_id, laboratory_id) VALUES ($1, $2, $3, $4) ON CONFLICT DO NOTHING`,
			id, role, assignedLocationID, nil)
	}
	return id, nil
}

func (s *Store) UpdateUserAccess(userID string, roles []string, certifications interface{}, active *bool, assignedLocationID string) error {
	if active != nil {
		s.db.Exec(`UPDATE users SET active=$2 WHERE id=$1`, userID, *active)
	}
	if roles != nil {
		s.db.Exec(`DELETE FROM user_roles WHERE user_id=$1`, userID)
		for _, role := range roles {
			s.db.Exec(`INSERT INTO user_roles (user_id, role, node_id, laboratory_id) VALUES ($1, $2, $3, $4) ON CONFLICT DO NOTHING`,
				userID, role, assignedLocationID, nil)
		}
	}
	return nil
}

func (s *Store) InsertTimeline(eventID int, action, actorID, role, entityType, entityID string, success bool, details map[string]interface{}) error {
	detJSON, _ := json.Marshal(details)
	_, err := s.db.Exec(`INSERT INTO timeline (event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details) VALUES ($1,$2,$3,$4,$5,$6,$7,now(),$8)`,
		eventID, action, actorID, role, entityType, entityID, success, string(detJSON))
	return err
}

func (s *Store) NextTimelineEventID() int {
	var id int
	s.db.QueryRow(`SELECT COALESCE(MAX(event_id), 0) + 1 FROM timeline`).Scan(&id)
	return id
