func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, models.ErrorEnvelope{Error: message, Code: code})
}

func getToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	return r.URL.Query().Get("token")
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		token := getToken(r)
		if token == "" {
			writeError(w, 401, "UNAUTHORIZED", "missing authorization")
			return
		}
		payload, err := auth.ValidateToken(token)
		if err != nil {
			writeError(w, 401, "UNAUTHORIZED", err.Error())
			return
		}
		ctx := context.WithValue(r.Context(), "userID", payload.UserID)
		ctx = context.WithValue(ctx, "sessionID", payload.SessionID)
		ctx = context.WithValue(ctx, "activeRole", payload.Role)
		next(w, r.WithContext(ctx))
	}
}

func requireRole(roles ...string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return authMiddleware(func(w http.ResponseWriter, r *http.Request) {
			role := r.Context().Value("activeRole").(string)
			for _, allowed := range roles {
				if role == allowed {
					next(w, r)
					return
				}
			}
			writeError(w, 403, "FORBIDDEN", "insufficient permissions")
		})
	}
}

func getCurrentUserID(r *http.Request) string {
	return r.Context().Value("userID").(string)
}

func getCurrentRole(r *http.Request) string {
	r := r.Context().Value("activeRole").(string)
	if r == "" {
