}

func getStr(m map[string]interface{}, key string) string {
	if v, ok := m[key].(string); ok {
		return v
	}
	return ""
}

func nextEventID() int64 {
	eventMu.Lock()
	defer eventMu.Unlock()
	eventCounter++
