				roles = append(roles, s)
			}
		}
	}
	assignedLocationID := getStr(body, "assignedLocationId")

	userID, err := store.CreateUser(username, password, fullName, email, roles, assignedLocationID)
	if err != nil {
		writeError(w, 409, "CONFLICT", err.Error())
		return
	}

	// Handle certifications
	if certs, ok := body["certifications"].([]interface{}); ok {
		for _, c := range certs {
			if cm, ok := c.(map[string]interface{}); ok {
				code := getStr(cm, "code")
				store.AddCertification(userID, code)
			}
		}
	}

	auditDB.Record(context.Background(), "user.create", getCurrentUserID(r), getCurrentRole(r), "user", userID, true, nil)
	writeJSON(w, 201, map[string]interface{}{"userId": userID})
}

