// POST /api/search-audit-trail
func handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	var body map[string]interface{}
	if err := parseJSON(r, &body); err != nil {
		writeError(w, 400, "BAD_REQUEST", "invalid JSON")
		return
	}
	limit := 50
	if l, ok := body["limit"].(float64); ok {
		limit = int(l)
	}
	offset := 0
	if o, ok := body["offset"].(float64); ok {
		offset = int(o)
	}
	order := "newest_first"
	if o, ok := body["order"].(string); ok && o != "" {
		order = o
	}

	entries, total, err := auditDB.Search(context.Background(), body, limit, offset, order)
	if err != nil {
		writeError(w, 500, "INTERNAL", err.Error())
		return
	}
	if entries == nil {
		entries = []models.AuditEntry{}
	}

	hasMore := offset+limit < total
	nextOffset := offset + limit
	resp := models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}
	writeJSON(w, 200, resp)
}

