// GET /ready
func handleReady(w http.ResponseWriter, r *http.Request) {
	// Check all datastores
	ctx := context.Background()
	pgOK := store.DB().Ping() == nil
	redisOK := eventsDB.Ping(ctx) == nil
	mongoOK := auditDB.Ping(ctx) == nil

	if pgOK && redisOK && mongoOK {
		writeJSON(w, 200, map[string]string{"status": "ready"})
	} else {
		status := "error"
		if !pgOK {
			status = "postgresql unavailable"
		} else if !redisOK {
			status = "redis unavailable"
		} else if !mongoOK {
			status = "mongodb unavailable"
		}
		writeJSON(w, 503, map[string]string{"status": status})
	}
}

// ======================= MAIN =======================

func main() {
	initOnly := flag.Bool("init-only", false, "Initialize database schema and exit")
	flag.Parse()

	pgHost := os.Getenv("PGHOST")
	if pgHost == "" {
		pgHost = "127.0.0.1"
	}
	pgPort, _ := strconv.Atoi(os.Getenv("PGPORT"))
	if pgPort == 0 {
		pgPort = 15432
	}
	pgUser := os.Getenv("PGUSER")
	if pgUser == "" {
		pgUser = "agent"
	}
	pgPass := os.Getenv("PGPASSWORD")
	pgDB := os.Getenv("PGDATABASE")
	if pgDB == "" {
		pgDB = "agent"
	}

	mongoURI := os.Getenv("MONGO_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017"
	}
	redisAddr := os.Getenv("REDIS_ADDR")
	if redisAddr == "" {
		redisAddr = "127.0.0.1:6379"
	}

	var err error
	store, err = pgstore.New(pgHost, pgPort, pgUser, pgPass, pgDB)
	if err != nil {
		log.Fatalf("PostgreSQL connection failed: %v", err)
	}
	defer store.Close()
	log.Println("PostgreSQL connected")

	if *initOnly {
		if err := store.Init(); err != nil {
			log.Fatalf("Schema initialization failed: %v", err)
		}
		log.Println("Schema initialized: all tables and indexes created")
		return
	}

	// Ensure schema exists
	store.Init()

	auditDB, err = mongo.New(mongoURI)
	if err != nil {
		log.Fatalf("MongoDB connection failed: %v", err)
	}
	defer auditDB.Close(context.Background())
	auditDB.Init(context.Background())
	log.Println("MongoDB connected")

	eventsDB, err = redisstore.New(redisAddr)
	if err != nil {
		log.Fatalf("Redis connection failed: %v", err)
	}
	defer eventsDB.Close()
	eventsDB.Init(context.Background())
	log.Println("Redis connected")

	svcCalc = serviceability.New(store)
	svcCalc.Compute()
	log.Println("Serviceability computed")

	// Seed default sample types if none exist
	store.SeedSampleTypes()
	// Create admin user if set
	adminUser := os.Getenv("ADMIN_USERNAME")
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminUser != "" && adminPass != "" {
		if err := store.CreateAdminIfNotExists(adminUser, adminPass); err != nil {
			log.Printf("Admin user note: %v", err)
		} else {
			log.Printf("Created admin user: %s", adminUser)
		}
	}

	// Wire routes
	mux := http.NewServeMux()

	// Auth
	mux.HandleFunc("POST /api/authenticate-user", handleAuthenticateUser)
	mux.HandleFunc("POST /api/select-active-role", authMiddleware(handleSelectActiveRole))

	// Serviceability
	mux.HandleFunc("POST /api/check-serviceability", authMiddleware(handleCheckServiceability))
	mux.HandleFunc("POST /api/read-serviceability-snapshot", authMiddleware(handleReadServiceabilitySnapshot))

	// Samples
	mux.HandleFunc("POST /api/create-collection-request", authMiddleware(handleCreateCollectionRequest))
	mux.HandleFunc("POST /api/ingest-presealed-sample", authMiddleware(handleIngestPresealedSample))
	mux.HandleFunc("POST /api/collect-and-seal-sample", requireRole("collection_professional")(handleCollectAndSealSample))
	mux.HandleFunc("GET /api/read-sample-state/", authMiddleware(handleReadSampleState))
	mux.HandleFunc("POST /api/read-sample-lifecycle", authMiddleware(handleReadSampleLifecycle))

	// Journey
	mux.HandleFunc("POST /api/read-journey-plan", authMiddleware(handleReadJourneyPlan))
	mux.HandleFunc("POST /api/cancel-journey", requireRole("dispatcher", "administrator")(handleCancelJourney))
	mux.HandleFunc("POST /api/split-journey", requireRole("dispatcher", "administrator")(handleSplitJourney))
	mux.HandleFunc("POST /api/merge-journeys", requireRole("dispatcher", "administrator")(handleMergeJourneys))
	mux.HandleFunc("POST /api/reroute-journey", requireRole("dispatcher", "administrator")(handleRerouteJourney))
	mux.HandleFunc("POST /api/edit-active-plan", requireRole("dispatcher", "administrator")(handleEditActivePlan))

	// Assignments
	mux.HandleFunc("POST /api/accept-assignment", authMiddleware(handleAcceptAssignment))
	mux.HandleFunc("POST /api/decline-assignment", authMiddleware(handleDeclineAssignment))
	mux.HandleFunc("POST /api/update-assignment-progress", authMiddleware(handleUpdateAssignmentProgress))

	// Handoffs
	mux.HandleFunc("POST /api/initiate-handoff", authMiddleware(handleInitiateHandoff))
	mux.HandleFunc("POST /api/confirm-handoff", authMiddleware(handleConfirmHandoff))

	// Worker
	mux.HandleFunc("POST /api/record-worker-location", authMiddleware(handleRecordWorkerLocation))
	mux.HandleFunc("POST /api/record-handling-checkpoint", authMiddleware(handleRecordHandlingCheckpoint))
	mux.HandleFunc("POST /api/set-worker-availability", authMiddleware(handleSetWorkerAvailability))

	// Lab
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", requireRole("laboratory_team")(handleConfirmLaboratoryReceipt))
	mux.HandleFunc("POST /api/record-laboratory-exception", requireRole("laboratory_team")(handleRecordLaboratoryException))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", requireRole("administrator")(handleConfigureLaboratoryAcceptance))

	// Capacity
	mux.HandleFunc("POST /api/configure-capacity", requireRole("administrator")(handleConfigureCapacity))

	// Locations
	mux.HandleFunc("POST /api/create-location", requireRole("administrator")(handleCreateLocation))
	mux.HandleFunc("POST /api/update-location", requireRole("administrator")(handleUpdateLocation))
	mux.HandleFunc("POST /api/set-location-status", requireRole("administrator")(handleSetLocationStatus))
	mux.HandleFunc("POST /api/set-location-function-status", requireRole("administrator")(handleSetLocationFunctionStatus))

	// Connections
	mux.HandleFunc("POST /api/create-connection", requireRole("administrator")(handleCreateConnection))
	mux.HandleFunc("POST /api/set-connection-status", requireRole("administrator")(handleSetConnectionStatus))

	// Sample types
	mux.HandleFunc("POST /api/create-sample-type", requireRole("administrator")(handleCreateSampleType))
	mux.HandleFunc("POST /api/update-sample-type", requireRole("administrator")(handleUpdateSampleType))

	// Users
	mux.HandleFunc("POST /api/create-user", requireRole("administrator")(handleCreateUser))
	mux.HandleFunc("POST /api/update-user-access", requireRole("administrator")(handleUpdateUserAccess))
	mux.HandleFunc("GET /api/read-user/", requireRole("administrator")(handleReadUser))

	// Operations
	mux.HandleFunc("POST /api/list-role-work", authMiddleware(handleListRoleWork))
	mux.HandleFunc("POST /api/read-operations-state", requireRole("dispatcher", "administrator")(handleReadOperationsState))
	mux.HandleFunc("POST /api/search-audit-trail", requireRole("dispatcher", "administrator")(handleSearchAuditTrail))
	mux.HandleFunc("POST /api/report-disruption", requireRole("dispatcher", "administrator")(handleReportDisruption))

	// UI & Events
	mux.HandleFunc("GET /api/ui/bootstrap", authMiddleware(handleUIBootstrap))
	mux.HandleFunc("GET /api/events", authMiddleware(handleEvents))

	// Readiness
	mux.HandleFunc("GET /ready", handleReady)
	mux.HandleFunc("GET /api/ready", handleReady)

	// CORS
	handler := corsMiddleware(mux)

	log.Println("Starting server on :8080")
	if err := http.ListenAndServe(":8080", handler); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE,OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization,Content-Type")
		if r.Method == "OPTIONS" {
			w.WriteHeader(200)
			return
		}
		next.ServeHTTP(w, r)
	})
}
